// MediaPlayer: switch-based hierarchical state machine generated by MachinaState.
// Do not edit by hand. Derive from this class and implement the guard and action hooks.
#pragma once

#include <cstddef>

namespace Demo {

    class MediaPlayer {
      public:
        enum class State {
            Stopped,
            Active,
            Playing,   // in Active
            Paused,   // in Active
            Ejected,
            None
        };

        enum class Event {
            Play,
            Pause,
            Stop,
            TrackEnd,
            Eject,
            Resume,
            Volume
        };

        enum class TraceKind {
            Start,        // name = machine name
            Event,        // name = event being dispatched
            Ignored,      // name = event no state handled
            Transition,   // name = "Source -> Target"
            Exit,         // name = state being exited
            Enter         // name = state being entered
        };

        static constexpr std::size_t kStateCount  = 5;
        static constexpr std::size_t kEventCount  = 7;
        static constexpr std::size_t kRegionCount = 2;   // region 0 is the top level
        static constexpr std::size_t kQueueCapacity = 16;

        virtual ~MediaPlayer() = default;

        // Resets the machine (running timers are cancelled, history is forgotten) and enters the initial state configuration.
        void Start() {
            const ScopedLock lock(*this);
            for (State& state : active_) {
                state = State::None;
            }
            for (State& state : history_) {
                state = State::None;
            }
            queueHead_  = 0;
            queueCount_ = 0;
            Trace(TraceKind::Start, "MediaPlayer");
            EnterDown(State::None, State::Stopped, false);
            DrainQueue();
        }

        // Dispatches an event to the innermost active states first. Returns false if the event was not handled.
        bool Dispatch(Event event) {
            const ScopedLock lock(*this);
            switch (event) {
                case Event::Volume:
                    return false;   // use the typed Dispatch method / internal event
                default:
                    break;
            }
            args_ = nullptr;
            const bool handled = DispatchCore(event);
            args_ = nullptr;
            DrainQueue();
            return handled;
        }

        bool DispatchVolume(int level) {
            const ScopedLock lock(*this);
            const VolumeArgs args { level };
            args_ = &args;
            const bool handled = DispatchCore(Event::Volume);
            args_ = nullptr;
            DrainQueue();
            return handled;
        }

        // Innermost active state (following the first region of orthogonal states).
        State Current() const {
            const ScopedLock lock(*this);
            return Innermost(active_[0]);
        }

        // True if the given state is active.
        bool IsIn(State state) const {
            const ScopedLock lock(*this);
            return state != State::None && active_[RegionOf(state)] == state;
        }

        // True once a top-level final state has been reached.
        bool IsFinished() const {
            const ScopedLock lock(*this);
            return active_[0] == State::Ejected;
        }

        static State ParentOf(State state) {
            switch (state) {
                case State::Playing:
                case State::Paused:
                    return State::Active;
                default:
                    return State::None;
            }
        }

        static const char* StateName(State state) {
            switch (state) {
                case State::Stopped:
                    return "Stopped";
                case State::Active:
                    return "Active";
                case State::Playing:
                    return "Playing";
                case State::Paused:
                    return "Paused";
                case State::Ejected:
                    return "Ejected";
                default:
                    return "None";
            }
        }

        static const char* EventName(Event event) {
            switch (event) {
                case Event::Play:
                    return "Play";
                case Event::Pause:
                    return "Pause";
                case Event::Stop:
                    return "Stop";
                case Event::TrackEnd:
                    return "TrackEnd";
                case Event::Eject:
                    return "Eject";
                case Event::Resume:
                    return "Resume";
                case Event::Volume:
                    return "Volume";
                default:
                    return "";
            }
        }

      protected:
        // Mutual exclusion around every public member, e.g. backed by a mutable std::mutex.
        // Hooks must not call public members of this class unless the lock is recursive.
        virtual void Lock() const   = 0;
        virtual void Unlock() const = 0;
        // Override to log state machine activity.
        virtual void Trace(TraceKind kind, const char* name) {
            (void)kind;
            (void)name;
        }
        // Queues an event from inside a hook; it is processed after the current event. Returns false if the queue is full.
        bool Post(Event event) {
            switch (event) {
                case Event::Volume:
                    return false;
                default:
                    break;
            }
            QueuedEvent entry {};
            entry.event = event;
            return Enqueue(entry);
        }
        bool PostVolume(int level) {
            QueuedEvent entry {};
            entry.event = Event::Volume;
            entry.Volume_level = level;
            return Enqueue(entry);
        }
        // Guards
        virtual bool hasNextTrack() = 0;
        // Actions
        virtual void powerOnAmp() = 0;
        virtual void powerOffAmp() = 0;
        virtual void startPlayback() = 0;
        virtual void stopPlayback() = 0;
        virtual void resetPosition() = 0;
        virtual void nextTrack() = 0;
        virtual void setVolume(int level) = 0;

      private:
        class ScopedLock {
          public:
            explicit ScopedLock(const MediaPlayer& owner) : owner_(owner) {
                owner_.Lock();
            }
            ~ScopedLock() {
                owner_.Unlock();
            }
            ScopedLock(const ScopedLock&)            = delete;
            ScopedLock& operator=(const ScopedLock&) = delete;

          private:
            const MediaPlayer& owner_;
        };

        // Arguments of the event being dispatched; only valid during Dispatch.
        struct VolumeArgs {
            int level;
        };
        const VolumeArgs& ArgsOfVolume() const {
            return *static_cast<const VolumeArgs*>(args_);
        }

        const void* args_ = nullptr;

        struct QueuedEvent {
            Event event;
            int Volume_level;
        };

        bool Enqueue(const QueuedEvent& entry) {
            if (queueCount_ == kQueueCapacity) {
                return false;
            }
            queue_[(queueHead_ + queueCount_) % kQueueCapacity] = entry;
            ++queueCount_;
            return true;
        }

        void DrainQueue() {
            while (queueCount_ > 0) {
                const QueuedEvent entry = queue_[queueHead_];
                queueHead_              = (queueHead_ + 1) % kQueueCapacity;
                --queueCount_;
                switch (entry.event) {
                    case Event::Volume: {
                        const VolumeArgs args { entry.Volume_level };
                        args_ = &args;
                        DispatchCore(entry.event);
                        args_ = nullptr;
                        break;
                    }
                    default:
                        DispatchCore(entry.event);
                        break;
                }
            }
        }

        bool DispatchCore(Event event) {
            Trace(TraceKind::Event, EventName(event));
            if (active_[0] != State::None && DispatchState(active_[0], event)) {
                return true;
            }
            Trace(TraceKind::Ignored, EventName(event));
            return false;
        }

        // Offers the event to every active region below `state` first, then to `state` itself.
        bool DispatchState(State state, Event event) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                if (active_[region] != State::None && DispatchState(active_[region], event)) {
                    return true;
                }
            }
            return HandleEvent(state, event);
        }

        bool HandleEvent(State state, Event event) {
            switch (state) {
                case State::Stopped:
                    switch (event) {
                        case Event::Play:
                            Trace(TraceKind::Transition, "Stopped -> Active");
                            ExitState(State::Stopped);
                            EnterDown(State::None, State::Active, false);
                            return true;
                        case Event::Eject:
                            Trace(TraceKind::Transition, "Stopped -> Ejected");
                            ExitState(State::Stopped);
                            EnterDown(State::None, State::Ejected, false);
                            return true;
                        case Event::Resume:
                            Trace(TraceKind::Transition, "Stopped -> Active (history)");
                            ExitState(State::Stopped);
                            EnterDown(State::None, State::Active, true);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Active:
                    switch (event) {
                        case Event::Stop:
                            Trace(TraceKind::Transition, "Active -> Stopped");
                            ExitState(State::Active);
                            resetPosition();
                            EnterDown(State::None, State::Stopped, false);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Playing:
                    switch (event) {
                        case Event::Pause:
                            Trace(TraceKind::Transition, "Playing -> Paused");
                            ExitState(State::Playing);
                            EnterDown(State::Active, State::Paused, false);
                            return true;
                        case Event::TrackEnd:
                            if (hasNextTrack()) {
                                Trace(TraceKind::Transition, "Playing -> Playing");
                                ExitState(State::Playing);
                                nextTrack();
                                EnterDown(State::Active, State::Playing, false);
                                return true;
                            }
                            Trace(TraceKind::Transition, "Playing -> Stopped");
                            ExitState(State::Active);
                            EnterDown(State::None, State::Stopped, false);
                            return true;
                        case Event::Volume:
                            Trace(TraceKind::Transition, "Playing (internal)");
                            setVolume(ArgsOfVolume().level);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Paused:
                    switch (event) {
                        case Event::Play:
                            Trace(TraceKind::Transition, "Paused -> Playing");
                            ExitState(State::Paused);
                            EnterDown(State::Active, State::Playing, false);
                            return true;
                        default:
                            break;
                    }
                    break;
                default:
                    break;
            }
            return false;
        }

        static std::size_t RegionOf(State state) {
            switch (state) {
                case State::Playing:
                case State::Paused:
                    return 1;
                default:
                    return 0;
            }
        }

        static std::size_t FirstRegionOf(State state) {
            switch (state) {
                case State::Active:
                    return 1;
                default:
                    return 0;
            }
        }

        static std::size_t RegionsOf(State state) {
            switch (state) {
                case State::Active:
                    return 1;
                default:
                    return 0;
            }
        }

        void EnterRegion(std::size_t region) {
            switch (region) {
                case 1:
                    EnterDown(State::Active, State::Playing, false);
                    break;
                default:
                    break;
            }
        }

        void OnEntry(State state) {
            switch (state) {
                case State::Active:
                    powerOnAmp();
                    break;
                case State::Playing:
                    startPlayback();
                    break;
                default:
                    break;
            }
        }

        void OnExit(State state) {
            switch (state) {
                case State::Active:
                    powerOffAmp();
                    break;
                case State::Playing:
                    stopPlayback();
                    break;
                default:
                    break;
            }
        }

        void ExitState(State state) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first + RegionsOf(state); region-- > first;) {
                if (active_[region] != State::None) {
                    ExitState(active_[region]);
                }
            }
            Trace(TraceKind::Exit, StateName(state));
            OnExit(state);
            active_[RegionOf(state)] = State::None;
            history_[RegionOf(state)] = state;   // last state exited from its region
        }

        // Enters every state from below `from` down to `target`, then follows default (initial) transitions
        // or, with `history`, restores the configuration recorded below `target`.
        void EnterDown(State from, State target, bool history) {
            State state = target;
            State next  = State::None;
            while (ParentOf(state) != from) {
                next  = state;
                state = ParentOf(state);
            }
            EnterState(state);
            if (next == State::None) {
                if (history) {
                    EnterHistory(state, false);
                    return;
                }
                EnterDefault(state);
                return;
            }
            EnterDown(state, target, history);
        }

        void EnterState(State state) {
            active_[RegionOf(state)] = state;
            Trace(TraceKind::Enter, StateName(state));
            OnEntry(state);
        }

        void EnterDefault(State state) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                EnterRegion(region);
            }
        }

        // Restores the regions of `state` from the states last exited from them (recursively for deep history).
        void EnterHistory(State state, bool deep) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                const State remembered = history_[region];
                if (remembered == State::None) {
                    EnterRegion(region);
                } else if (deep) {
                    EnterState(remembered);
                    EnterHistory(remembered, true);
                } else {
                    EnterDown(state, remembered, false);
                }
            }
        }

        State Innermost(State state) const {
            while (state != State::None && RegionsOf(state) > 0 && active_[FirstRegionOf(state)] != State::None) {
                state = active_[FirstRegionOf(state)];
            }
            return state;
        }

        State active_[kRegionCount] = { State::None, State::None };   // active state per region
        State history_[kRegionCount] = { State::None, State::None };   // state last exited per region
        QueuedEvent queue_[kQueueCapacity] = {};
        std::size_t queueHead_  = 0;
        std::size_t queueCount_ = 0;
    };
}
